//! Compiled-kernel cache.
//!
//! Every kernel shares one pipeline layout: no descriptor sets, and a
//! [`PUSH_CONSTANT_BYTES`]-byte push-constant block that carries tensor
//! pointers and scalars. Pipelines are keyed by (kernel name, specialization
//! constants) and the driver's compiled code is persisted between runs in a
//! `VkPipelineCache` file.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;

use ash::vk;

use crate::{Context, Result};

// `pub static SPIRV: &[(&str, &[u8])]`, generated by build.rs from shaders/*.slang.
include!(concat!(env!("OUT_DIR"), "/kernels.rs"));

/// Push-constant block size for every kernel (Vulkan's guaranteed minimum).
pub const PUSH_CONSTANT_BYTES: u32 = 128;

pub struct Kernel {
    pub name: String,
    pub pipeline: vk::Pipeline,
}

pub struct KernelCache {
    ctx: Arc<Context>,
    layout: vk::PipelineLayout,
    cache: vk::PipelineCache,
    cache_file: Option<PathBuf>,
    kernels: HashMap<(String, Vec<u32>), Arc<Kernel>>,
}

/// `TORCH_VK_CACHE_DIR`, else `%LOCALAPPDATA%\torch-vulkan` (or `$XDG_CACHE_HOME`/`~/.cache`).
fn cache_file() -> Option<PathBuf> {
    let dir = std::env::var_os("TORCH_VK_CACHE_DIR")
        .map(PathBuf::from)
        .or_else(|| std::env::var_os("LOCALAPPDATA").map(|d| PathBuf::from(d).join("torch-vulkan")))
        .or_else(|| std::env::var_os("XDG_CACHE_HOME").map(|d| PathBuf::from(d).join("torch-vulkan")))
        .or_else(|| std::env::var_os("HOME").map(|d| PathBuf::from(d).join(".cache").join("torch-vulkan")))?;
    Some(dir.join("pipelines.bin"))
}

impl KernelCache {
    pub fn new(ctx: Arc<Context>) -> Result<Self> {
        let cache_file = cache_file();
        // The driver validates the header (vendor, device, driver UUID) and
        // ignores data from another GPU or driver version.
        let initial = cache_file.as_ref().and_then(|p| std::fs::read(p).ok()).unwrap_or_default();
        unsafe {
            let range = vk::PushConstantRange::default().stage_flags(vk::ShaderStageFlags::COMPUTE).size(PUSH_CONSTANT_BYTES);
            let layout = ctx
                .device
                .create_pipeline_layout(&vk::PipelineLayoutCreateInfo::default().push_constant_ranges(std::slice::from_ref(&range)), None)?;
            let cache = ctx.device.create_pipeline_cache(&vk::PipelineCacheCreateInfo::default().initial_data(&initial), None)?;
            Ok(Self { ctx, layout, cache, cache_file, kernels: HashMap::new() })
        }
    }

    pub fn layout(&self) -> vk::PipelineLayout {
        self.layout
    }

    pub fn names() -> impl Iterator<Item = &'static str> {
        SPIRV.iter().map(|(n, _)| *n)
    }

    /// The pipeline for `name`, with specialization constants `spec[i]` bound
    /// to `constant_id = i`. Compiled on first use, then cached.
    pub fn get(&mut self, name: &str, spec: &[u32]) -> Result<Arc<Kernel>> {
        let key = (name.to_owned(), spec.to_vec());
        if let Some(k) = self.kernels.get(&key) {
            return Ok(k.clone());
        }
        let spirv = SPIRV.iter().find(|(n, _)| *n == name).ok_or_else(|| format!("unknown kernel {name}"))?.1;
        let mut words = ash::util::read_spv(&mut std::io::Cursor::new(spirv))?;
        let caps = self.ctx.caps;
        let declared = declared_capabilities(&words);
        let required = [
            (CAP_FLOAT64, caps.shader_float64, "shaderFloat64"),
            (CAP_INT64, caps.shader_int64, "shaderInt64"),
            (CAP_INT16, caps.shader_int16, "shaderInt16"),
            (CAP_FLOAT16, caps.shader_float16, "shaderFloat16"),
            (CAP_INT8, caps.shader_int8, "shaderInt8"),
            (CAP_STORAGE_16BIT, caps.storage_buffer_16bit, "storageBuffer16BitAccess"),
            (CAP_STORAGE_8BIT, caps.storage_buffer_8bit, "storageBuffer8BitAccess"),
            (CAP_SUBGROUP_BALLOT, caps.subgroup_ops.contains(vk::SubgroupFeatureFlags::BALLOT), "subgroup ballots"),
            (CAP_SUBGROUP_SHUFFLE, caps.subgroup_ops.contains(vk::SubgroupFeatureFlags::SHUFFLE), "subgroup shuffles"),
            (CAP_COOPERATIVE_MATRIX, caps.cooperative_matrix_f16 || caps.cooperative_matrix_bf16, "cooperative matrices (VK_KHR_cooperative_matrix)"),
            (CAP_BFLOAT16_TYPE, caps.cooperative_matrix_bf16, "bfloat16 (VK_KHR_shader_bfloat16)"),
            (CAP_BFLOAT16_COOPERATIVE_MATRIX, caps.cooperative_matrix_bf16, "bfloat16 cooperative matrices"),
        ];
        for (cap, have, what) in required {
            if declared.contains(&cap) && !have {
                return Err(format!("kernel {name} needs {what}, which this device does not support").into());
            }
        }
        strip_denorm_preserve(&mut words, !caps.denorm_preserve_f32, !caps.denorm_preserve_f64);
        if caps.nan_preserve_f64 && declared.contains(&CAP_FLOAT64) {
            add_nan_preserve_f64(&mut words);
        }
        let d = &self.ctx.device;
        unsafe {
            let module = d.create_shader_module(&vk::ShaderModuleCreateInfo::default().code(&words), None)?;
            let entries: Vec<_> =
                (0..spec.len() as u32).map(|i| vk::SpecializationMapEntry::default().constant_id(i).offset(i * 4).size(4)).collect();
            let data: Vec<u8> = spec.iter().flat_map(|v| v.to_ne_bytes()).collect();
            let spec_info = vk::SpecializationInfo::default().map_entries(&entries).data(&data);
            let mut stage = vk::PipelineShaderStageCreateInfo::default().stage(vk::ShaderStageFlags::COMPUTE).module(module).name(c"main");
            if !spec.is_empty() {
                stage = stage.specialization_info(&spec_info);
            }
            // Kernels written for subgroups run with a fixed number of lanes,
            // every subgroup full (otherwise the size a shader sees need not
            // be the one it runs at: Intel reports 32 and may run 16).
            let lanes = kernel_subgroup_size(&caps, name);
            let mut required = vk::PipelineShaderStageRequiredSubgroupSizeCreateInfo::default().required_subgroup_size(lanes);
            if subgroup_preference(name).is_some() {
                if lanes == 0 {
                    d.destroy_shader_module(module, None);
                    return Err(format!("kernel {name} needs subgroup size control, which this device does not support").into());
                }
                stage = stage.flags(vk::PipelineShaderStageCreateFlags::REQUIRE_FULL_SUBGROUPS).push_next(&mut required);
            }
            let info = vk::ComputePipelineCreateInfo::default().stage(stage).layout(self.layout);
            let result = d.create_compute_pipelines(self.cache, &[info], None);
            d.destroy_shader_module(module, None);
            let pipeline = result.map_err(|(_, e)| e)?[0];
            // (Intel's Windows driver has returned success with no pipeline
            // for kernels its compiler could not handle)
            if pipeline == vk::Pipeline::null() {
                return Err(format!("the driver could not compile kernel {name} (no pipeline, no error)").into());
            }
            let kernel = Arc::new(Kernel { name: name.to_owned(), pipeline });
            self.kernels.insert(key, kernel.clone());
            Ok(kernel)
        }
    }

    fn save(&self) {
        let Some(path) = &self.cache_file else { return };
        let Ok(data) = (unsafe { self.ctx.device.get_pipeline_cache_data(self.cache) }) else { return };
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        // Write to a temporary file and rename, so concurrent processes never
        // see a half-written cache.
        let tmp = path.with_extension(format!("tmp{}", std::process::id()));
        if std::fs::write(&tmp, data).is_ok() {
            let _ = std::fs::rename(&tmp, path);
        }
    }
}

const OP_CAPABILITY: u32 = 17;
const CAP_FLOAT16: u32 = 9;
const CAP_FLOAT64: u32 = 10;
const CAP_INT64: u32 = 11;
const CAP_INT16: u32 = 22;
const CAP_INT8: u32 = 39;
const CAP_STORAGE_16BIT: u32 = 4433;
const CAP_STORAGE_8BIT: u32 = 4448;
const CAP_SUBGROUP_BALLOT: u32 = 64;  // GroupNonUniformBallot (broadcasts)
const CAP_SUBGROUP_SHUFFLE: u32 = 65; // GroupNonUniformShuffle
const CAP_COOPERATIVE_MATRIX: u32 = 6022; // CooperativeMatrixKHR
const CAP_BFLOAT16_TYPE: u32 = 5116; // BFloat16TypeKHR
const CAP_BFLOAT16_COOPERATIVE_MATRIX: u32 = 5118; // BFloat16CooperativeMatrixKHR

/// Kernels (by name prefix, first match) written for a fixed subgroup size,
/// with the size each prefers.
const SUBGROUP_KERNELS: &[(&str, u32)] = &[("gemmsg_f64", 8), ("gemmsg", 16), ("gemmcm", 32)];

fn subgroup_preference(name: &str) -> Option<u32> {
    SUBGROUP_KERNELS.iter().find(|(k, _)| name.starts_with(k)).map(|&(_, s)| s)
}

/// The subgroup size kernel `name` runs with: 0 for kernels not written for
/// subgroups, and for those where the device cannot run them.
pub fn kernel_subgroup_size(caps: &crate::context::Capabilities, name: &str) -> u32 {
    subgroup_preference(name).map_or(0, |s| caps.subgroup_size_for(s))
}

/// The capabilities a SPIR-V module declares (its `OpCapability` operands).
pub fn declared_capabilities(words: &[u32]) -> Vec<u32> {
    let mut caps = Vec::new();
    let mut i = 5;
    while i < words.len() {
        let count = (words[i] >> 16) as usize;
        if words[i] & 0xffff == OP_CAPABILITY && count == 2 {
            caps.push(words[i + 1]);
        }
        i += count.max(1);
    }
    caps
}

/// Removes `OpExecutionMode DenormPreserve` for the given float widths (and
/// the `DenormPreserve` capability once no such mode remains, with the
/// `SPV_KHR_float_controls` extension that SPIR-V 1.3 modules declare for
/// it). The kernels are compiled to preserve denormals; a device that cannot
/// must not see that request, and then flushes denormals to zero instead.
pub fn strip_denorm_preserve(words: &mut Vec<u32>, width32: bool, width64: bool) {
    const OP_EXECUTION_MODE: u32 = 16;
    const DENORM_PRESERVE_MODE: u32 = 4459;
    const DENORM_PRESERVE_CAPABILITY: u32 = 4464;
    if (!width32 && !width64) || words.len() < 5 {
        return;
    }
    let mut out = words[..5].to_vec();
    const OP_EXTENSION: u32 = 10;
    let mut remaining_modes = 0;
    let mut i = 5;
    let mut capability_at = None;
    let mut extension_at = None;
    while i < words.len() {
        let count = (words[i] >> 16) as usize;
        let opcode = words[i] & 0xffff;
        if count == 0 || i + count > words.len() {
            return;  // malformed: leave the module untouched
        }
        let inst = &words[i..i + count];
        let drop = if opcode == OP_EXECUTION_MODE && count >= 4 && inst[2] == DENORM_PRESERVE_MODE {
            let strip = (inst[3] == 32 && width32) || (inst[3] == 64 && width64);
            if !strip {
                remaining_modes += 1;
            }
            strip
        } else {
            false
        };
        if opcode == OP_CAPABILITY && count == 2 && inst[1] == DENORM_PRESERVE_CAPABILITY {
            capability_at = Some(out.len());
        }
        if opcode == OP_EXTENSION && extension_name(&inst[1..]) == "SPV_KHR_float_controls" {
            extension_at = Some((out.len(), count));
        }
        if !drop {
            out.extend_from_slice(inst);
        }
        i += count;
    }
    if remaining_modes == 0 {
        // (later position first, so the earlier one stays valid)
        let mut spans: Vec<(usize, usize)> = capability_at.map(|at| (at, 2)).into_iter().chain(extension_at).collect();
        spans.sort_by_key(|&(at, _)| std::cmp::Reverse(at));
        for (at, n) in spans {
            out.drain(at..at + n);
        }
    }
    *words = out;
}

/// Adds `OpExecutionMode SignedZeroInfNanPreserve 64` (with its capability,
/// and `SPV_KHR_float_controls` if the module no longer declares it) to every
/// entry point: float64 NaNs, infinities and signed zeros kept as IEEE says.
/// Without it Mesa's ANV lowers a float64 1.0 / NaN to 0 (its software
/// reciprocal assumes finite inputs), so sigmoid(NaN) or i0e(NaN) came out 0.
pub fn add_nan_preserve_f64(words: &mut Vec<u32>) {
    const OP_ENTRY_POINT: u32 = 15;
    const OP_EXECUTION_MODE: u32 = 16;
    const OP_EXTENSION: u32 = 10;
    const NAN_PRESERVE_MODE: u32 = 4461;
    const NAN_PRESERVE_CAPABILITY: u32 = 4466;
    if words.len() < 5 {
        return;
    }
    let (mut last_capability, mut last_mode, mut first_entry) = (None, None, None);
    let mut entries = Vec::new();
    let mut has_extension = false;
    let mut i = 5;
    while i < words.len() {
        let count = (words[i] >> 16) as usize;
        let opcode = words[i] & 0xffff;
        if count == 0 || i + count > words.len() {
            return;  // malformed: leave the module untouched
        }
        let inst = &words[i..i + count];
        match opcode {
            OP_CAPABILITY if count == 2 => {
                if inst[1] == NAN_PRESERVE_CAPABILITY {
                    return;  // (already declared)
                }
                last_capability = Some(i + count);
            }
            OP_EXTENSION if extension_name(&inst[1..]) == "SPV_KHR_float_controls" => has_extension = true,
            OP_ENTRY_POINT if count >= 3 => {
                entries.push(inst[2]);
                first_entry.get_or_insert(i);
            }
            OP_EXECUTION_MODE => last_mode = Some(i + count),
            _ => {}
        }
        i += count;
    }
    let (Some(cap_at), Some(entry_at)) = (last_capability, first_entry) else { return };
    // Later positions first, so earlier ones stay valid.
    let modes: Vec<u32> = entries.iter().flat_map(|&id| [(4 << 16) | OP_EXECUTION_MODE, id, NAN_PRESERVE_MODE, 64]).collect();
    let mode_at = last_mode.unwrap_or_else(|| {
        // (after the entry points)
        let mut j = entry_at;
        while j < words.len() && words[j] & 0xffff == OP_ENTRY_POINT {
            j += (words[j] >> 16) as usize;
        }
        j
    });
    words.splice(mode_at..mode_at, modes);
    let mut header = vec![(2 << 16) | OP_CAPABILITY, NAN_PRESERVE_CAPABILITY];
    if !has_extension {
        let mut name: Vec<u8> = b"SPV_KHR_float_controls".to_vec();
        name.resize((name.len() / 4 + 1) * 4, 0);
        let packed: Vec<u32> = name.chunks(4).map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect();
        header.push((((packed.len() + 1) as u32) << 16) | OP_EXTENSION);
        header.extend(packed);
    }
    words.splice(cap_at..cap_at, header);
}

/// The literal string of an instruction operand (UTF-8, nul-terminated, packed
/// four bytes a word, little-endian).
fn extension_name(words: &[u32]) -> String {
    let bytes: Vec<u8> = words.iter().flat_map(|w| w.to_le_bytes()).take_while(|&b| b != 0).collect();
    String::from_utf8_lossy(&bytes).into_owned()
}

impl Drop for KernelCache {
    fn drop(&mut self) {
        self.save();
        unsafe {
            let d = &self.ctx.device;
            for k in self.kernels.values() {
                d.destroy_pipeline(k.pipeline, None);
            }
            d.destroy_pipeline_cache(self.cache, None);
            d.destroy_pipeline_layout(self.layout, None);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{add_nan_preserve_f64, declared_capabilities, strip_denorm_preserve, CAP_FLOAT64, SPIRV};

    // Header + OpCapability Shader + OpCapability DenormPreserve +
    // OpExecutionMode %4 DenormPreserve 32 + ... 64 + OpNop.
    fn module() -> Vec<u32> {
        vec![0x0723_0203, 0x0001_0500, 0, 10, 0, (2 << 16) | 17, 1, (2 << 16) | 17, 4464, (4 << 16) | 16, 4, 4459, 32,
             (4 << 16) | 16, 4, 4459, 64, (1 << 16)]
    }

    #[test]
    fn strips_one_width() {
        let mut w = module();
        strip_denorm_preserve(&mut w, false, true);
        assert_eq!(w.len(), module().len() - 4);
        assert!(w.windows(2).any(|p| p == [(2 << 16) | 17, 4464]), "capability kept for the float32 mode");
    }

    #[test]
    fn strips_both_widths_and_the_capability() {
        let mut w = module();
        strip_denorm_preserve(&mut w, true, true);
        assert_eq!(w, vec![0x0723_0203, 0x0001_0500, 0, 10, 0, (2 << 16) | 17, 1, (1 << 16)]);
    }

    #[test]
    fn untouched_when_supported() {
        let mut w = module();
        strip_denorm_preserve(&mut w, false, false);
        assert_eq!(w, module());
    }

    #[test]
    fn reads_capabilities() {
        assert_eq!(declared_capabilities(&module()), vec![1, 4464]);
    }

    /// Kernels without a float64/complex128 type must run on GPUs without
    /// shaderFloat64 (scalar parameters travel as raw 64-bit slots).
    #[test]
    fn kernels_need_float64_only_for_double_types() {
        let mut offenders = Vec::new();
        for (name, spirv) in SPIRV {
            // (square_plus_third: a test kernel of float64 arithmetic)
            if name.split('_').any(|part| part == "f64" || part == "c128") || *name == "square_plus_third" {
                continue;
            }
            let words = ash::util::read_spv(&mut std::io::Cursor::new(spirv)).unwrap();
            if declared_capabilities(&words).contains(&CAP_FLOAT64) {
                offenders.push(*name);
            }
        }
        assert!(offenders.is_empty(), "declare Float64: {offenders:?}");
    }

    #[test]
    fn adds_float64_nan_preservation() {
        // Header + OpCapability Shader + OpCapability Float64 + OpEntryPoint
        // GLCompute %4 "main" + OpExecutionMode %4 LocalSize 1 1 1 + OpNop.
        let main = u32::from_le_bytes(*b"main");
        let mut w = vec![0x0723_0203, 0x0001_0300, 0, 10, 0, (2 << 16) | 17, 1, (2 << 16) | 17, 10,
                         (5 << 16) | 15, 5, 4, main, 0, (6 << 16) | 16, 4, 17, 1, 1, 1, (1 << 16)];
        add_nan_preserve_f64(&mut w);
        let caps = declared_capabilities(&w);
        assert!(caps.contains(&4466) && caps.contains(&CAP_FLOAT64));
        let mode = w.windows(4).any(|m| m == [(4 << 16) | 16, 4, 4461, 64]);
        assert!(mode, "{w:?}");
        let ext = w.windows(2).any(|e| e[0] & 0xffff == 10 && e[1] == u32::from_le_bytes(*b"SPV_"));
        assert!(ext, "{w:?}");
        let n = w.len();
        add_nan_preserve_f64(&mut w);  // (once only)
        assert_eq!(w.len(), n);
    }

    /// build.rs removes every OpTypeForwardPointer (spirv_fix.rs).
    #[test]
    fn kernels_have_no_forward_pointers() {
        let offenders: Vec<&str> = SPIRV
            .iter()
            .filter(|(_, spirv)| {
                let words = ash::util::read_spv(&mut std::io::Cursor::new(spirv)).unwrap();
                crate::spirv_fix::has_forward_pointer(&words)
            })
            .map(|(name, _)| *name)
            .collect();
        assert!(offenders.is_empty(), "forward pointers left in: {offenders:?}");
    }
}
